import sqlite3
import hashlib
import hmac
import os
import re
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY', os.urandom(32))
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA journal_mode=WAL")
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT NOT NULL,
        user_id INTEGER,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_auth_token(token):
    """Verify HMAC-based auth token"""
    if not token or ':' not in token:
        return None
    parts = token.split(':', 2)
    if len(parts) != 3:
        return None
    user_id, timestamp, signature = parts
    expected = hmac.new(
        app.secret_key if isinstance(app.secret_key, bytes) else app.secret_key.encode(),
        f"{user_id}:{timestamp}".encode(),
        hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature, expected):
        return None
    return int(user_id)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        user_id = verify_auth_token(token)
        if user_id is None:
            return jsonify({'error': 'Unauthorized'}), 401
        g.current_user_id = user_id
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        user_id = verify_auth_token(token)
        if user_id is None:
            return jsonify({'error': 'Unauthorized'}), 401
        db = get_db()
        user = db.execute('SELECT role FROM users WHERE id = ?', (user_id,)).fetchone()
        if not user or user['role'] != 'admin':
            return jsonify({'error': 'Forbidden'}), 403
        g.current_user_id = user_id
        return f(*args, **kwargs)
    return decorated

class QueryBuilder:
    """Helper class for building safe parameterized queries"""

    def __init__(self, table):
        self.table = table
        self.conditions = []
        self.params = []
        self.order_by = None
        self.limit_val = None

    def where(self, column, operator, value):
        """Add a WHERE condition with parameterized value"""
        allowed_operators = ['=', '!=', '<', '>', '<=', '>=', 'LIKE', 'IN']
        if operator.upper() not in allowed_operators:
            raise ValueError(f"Invalid operator: {operator}")
        # Validate column name against injection
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', column):
            raise ValueError(f"Invalid column name: {column}")
        self.conditions.append(f"{column} {operator} ?")
        self.params.append(value)
        return self

    def where_in(self, column, values):
        """Add a WHERE IN condition"""
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', column):
            raise ValueError(f"Invalid column name: {column}")
        placeholders = ','.join(['?'] * len(values))
        self.conditions.append(f"{column} IN ({placeholders})")
        self.params.extend(values)
        return self

    def order(self, column, direction='ASC'):
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', column):
            raise ValueError(f"Invalid column name: {column}")
        if direction.upper() not in ('ASC', 'DESC'):
            raise ValueError(f"Invalid direction: {direction}")
        self.order_by = f"{column} {direction.upper()}"
        return self

    def limit(self, n):
        self.limit_val = int(n)
        return self

    def build_select(self, columns='*'):
        """Build SELECT query"""
        query = f"SELECT {columns} FROM {self.table}"
        if self.conditions:
            query += " WHERE " + " AND ".join(self.conditions)
        if self.order_by:
            query += f" ORDER BY {self.order_by}"
        if self.limit_val:
            query += f" LIMIT {self.limit_val}"
        return query, self.params

    def build_update(self, updates):
        """Build UPDATE query with parameterized values"""
        set_clauses = []
        update_params = []
        for col, val in updates.items():
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', col):
                raise ValueError(f"Invalid column name: {col}")
            set_clauses.append(f"{col} = ?")
            update_params.append(val)
        query = f"UPDATE {self.table} SET {', '.join(set_clauses)}"
        if self.conditions:
            query += " WHERE " + " AND ".join(self.conditions)
        return query, update_params + self.params


def search_users_by_criteria(db, criteria):
    """Search users based on multiple criteria - uses QueryBuilder for safety"""
    qb = QueryBuilder('users')

    if 'username' in criteria:
        qb.where('username', 'LIKE', f"%{criteria['username']}%")
    if 'email' in criteria:
        qb.where('email', 'LIKE', f"%{criteria['email']}%")
    if 'role' in criteria:
        qb.where('role', '=', criteria['role'])
    if 'active' in criteria:
        qb.where('active', '=', int(criteria['active']))

    # Apply sorting - validate against allowed columns
    allowed_sort_columns = {'username', 'email', 'role', 'active', 'id'}
    sort_col = criteria.get('sort', 'username')
    if sort_col not in allowed_sort_columns:
        raise ValueError(f"Invalid sort column: {sort_col}")
    sort_dir = criteria.get('direction', 'ASC')
    qb.order(sort_col, sort_dir)
    qb.limit(criteria.get('limit', 50))

    query, params = qb.build_select('id, username, email, role, active')
    return db.execute(query, params).fetchall()


def get_user_activity_report(db, user_id, filters):
    """Generate activity report for a user with optional filters"""
    base_query = "SELECT action, details, timestamp FROM audit_log WHERE user_id = ?"
    params = [user_id]

    if 'action_type' in filters:
        action_type = filters['action_type']
        # Validate action type against allowed values
        allowed_actions = ['login', 'logout', 'update_profile', 'change_password', 'admin_action']
        if action_type not in allowed_actions:
            raise ValueError("Invalid action type")
        base_query += " AND action = ?"
        params.append(action_type)

    if 'date_from' in filters:
        base_query += " AND timestamp >= ?"
        params.append(filters['date_from'])

    if 'date_to' in filters:
        base_query += " AND timestamp <= ?"
        params.append(filters['date_to'])

    # Sort order from user input - validated
    sort_order = filters.get('sort_order', 'DESC')
    if sort_order.upper() in ('ASC', 'DESC'):
        base_query += f" ORDER BY timestamp {sort_order.upper()}"

    return db.execute(base_query, params).fetchall()


def log_audit_event(db, user_id, action, details):
    """Log an audit event"""
    db.execute(
        'INSERT INTO audit_log (user_id, action, details) VALUES (?, ?, ?)',
        (user_id, action, details)
    )
    db.commit()


@app.route('/api/users/search', methods=['POST'])
@require_admin
def search_users():
    """Admin endpoint to search users"""
    criteria = request.get_json()
    if not criteria:
        return jsonify({'error': 'No criteria provided'}), 400

    db = get_db()
    try:
        results = search_users_by_criteria(db, criteria)
        users = [dict(row) for row in results]
        log_audit_event(db, g.current_user_id, 'admin_action', f'searched users: {len(users)} results')
        return jsonify({'users': users})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400


@app.route('/api/users/<int:user_id>/activity', methods=['GET'])
@require_auth
def get_activity(user_id):
    """Get activity report - users can only see their own"""
    if g.current_user_id != user_id:
        # Check if admin
        db = get_db()
        user = db.execute('SELECT role FROM users WHERE id = ?', (g.current_user_id,)).fetchone()
        if not user or user['role'] != 'admin':
            return jsonify({'error': 'Forbidden'}), 403

    db = get_db()
    filters = request.args.to_dict()
    try:
        results = get_user_activity_report(db, user_id, filters)
        events = [dict(row) for row in results]
        return jsonify({'activity': events})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400


@app.route('/api/users/bulk-update', methods=['POST'])
@require_admin
def bulk_update_users():
    """Bulk update user attributes"""
    data = request.get_json()
    if not data or 'user_ids' not in data or 'updates' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    user_ids = data['user_ids']
    updates = data['updates']

    # Validate user_ids are integers
    if not all(isinstance(uid, int) for uid in user_ids):
        return jsonify({'error': 'Invalid user IDs'}), 400

    # Only allow updating certain fields
    allowed_fields = {'role', 'active', 'email'}
    filtered_updates = {k: v for k, v in updates.items() if k in allowed_fields}

    if not filtered_updates:
        return jsonify({'error': 'No valid fields to update'}), 400

    db = get_db()
    try:
        qb = QueryBuilder('users')
        qb.where_in('id', user_ids)
        query, params = qb.build_update(filtered_updates)
        db.execute(query, params)
        db.commit()
        log_audit_event(db, g.current_user_id, 'admin_action', 
                       f'bulk updated {len(user_ids)} users: {list(filtered_updates.keys())}')
        return jsonify({'updated': len(user_ids)})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400


@app.route('/api/profile', methods=['PUT'])
@require_auth
def update_profile():
    """Update own profile"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    db = get_db()
    user_id = g.current_user_id

    # Build update dynamically based on provided fields
    allowed_fields = {'email'}
    updates = {}

    for field in allowed_fields:
        if field in data:
            updates[field] = data[field]

    if 'username' in data:
        new_username = data['username']
        # Validate username format
        if not re.match(r'^[a-zA-Z0-9_]{3,30}$', new_username):
            return jsonify({'error': 'Invalid username format'}), 400
        updates['username'] = new_username

    if not updates:
        return jsonify({'error': 'No valid fields to update'}), 400

    try:
        qb = QueryBuilder('users')
        qb.where('id', '=', user_id)
        query, params = qb.build_update(updates)
        db.execute(query, params)
        db.commit()
        log_audit_event(db, user_id, 'update_profile', f'updated: {list(updates.keys())}')
        return jsonify({'success': True})
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409
    except ValueError as e:
        return jsonify({'error': str(e)}), 400


@app.route('/api/reports/custom', methods=['POST'])
@require_admin
def custom_report():
    """Generate custom report with flexible filtering"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No report parameters'}), 400

    report_type = data.get('type', 'users')

    db = get_db()

    if report_type == 'users':
        criteria = data.get('criteria', {})
        results = search_users_by_criteria(db, criteria)
        return jsonify({'report': [dict(r) for r in results]})

    elif report_type == 'activity':
        # Custom activity report across all users
        target_user = data.get('user_id')
        filters = data.get('filters', {})

        if target_user:
            results = get_user_activity_report(db, target_user, filters)
        else:
            # All users activity - build query with parameterization
            query = "SELECT a.*, u.username FROM audit_log a JOIN users u ON a.user_id = u.id"
            conditions = []
            params = []

            if 'action' in filters:
                conditions.append("a.action = ?")
                params.append(filters['action'])
            if 'from_date' in filters:
                conditions.append("a.timestamp >= ?")
                params.append(filters['from_date'])
            if 'to_date' in filters:
                conditions.append("a.timestamp <= ?")
                params.append(filters['to_date'])

            if conditions:
                query += " WHERE " + " AND ".join(conditions)

            # Grouping restricted to allowed columns only
            group_by = data.get('group_by')
            if group_by:
                allowed_group_columns = {'a.action', 'a.user_id', 'u.username', 'date(a.timestamp)'}
                if group_by not in allowed_group_columns:
                    return jsonify({'error': 'Invalid group_by column'}), 400
                query += f" GROUP BY {group_by}"

            query += " ORDER BY a.timestamp DESC LIMIT 1000"
            results = db.execute(query, params).fetchall()

        return jsonify({'report': [dict(r) for r in results]})

    return jsonify({'error': 'Invalid report type'}), 400


